d = {"a": 1, "b": 2}
print(list(d.keys()))     # ['a', 'b']
print(list(d.values()))   # [1, 2]
print(list(d.items()))    # [('a', 1), ('b', 2)]

d.update({"b": 20, "c": 3})
print(d)                  # {'a': 1, 'b': 20, 'c': 3}
print(d.pop("a"))         # 1
print(d)                  # {'b': 20, 'c': 3}
print(d.setdefault("d", 4))  # 4
print(d)                  # {'b': 20, 'c': 3, 'd': 4}

scores = {"语文": 88, "数学": 95, "英语": 79}
for subject, score in scores.items():
    print(subject, score)

total = sum(scores.values())
print("平均分：", total / len(scores))   # 87.333...

count = {}
for ch in "banana":
    count[ch] = count.get(ch, 0) + 1
print(count)   # {'b': 1, 'a': 3, 'n': 2}

s = {1, 2}
s.add(3)
print(s)          # {1, 2, 3}
s.discard(9)      # 不报错
print(s)          # {1, 2, 3}
s.remove(1)
print(s)          # {2, 3}
print(s.pop())    # 随机返回一个元素
